1	import type { DocumentPickerResponse } from "@react-native-documents/picker";
2	import {
3	  type AudioMessageContent,
4	  EditedContent,
5	  type EventTimelineItem,
6	  type FileMessageContent,
7	  type ImageMessageContent,
8	  type Mentions,
9	  messageEventContentFromHtml,
10	  messageEventContentFromMarkdown,
11	  MessageType_Tags,
12	  MsgLikeKind_Tags,
13	  TimelineItemContent_Tags,
14	  type UploadParameters,
15	  UploadSource,
16	  type VideoMessageContent,
17	} from "@unomed/react-native-matrix-sdk";
18	import { MatrixCore } from "../../matrix-client/services/MatrixCore";
19	import { getEventId } from "../../matrix-client/utils";
20	
21	export type ForwardMessageType = "text" | "image" | "video" | "audio" | "file";
22	
23	export class TimelineService {
24	  public static sendMessage = async (
25	    roomId: string,
26	    message: string,
27	    mentions?: Mentions,
28	    htmlBody?: string,
29	  ) => {
30	    const room = MatrixCore.getRoom(roomId);
31	    const timeline = await room.timeline();
32	    if (!timeline) throw new Error("Timeline not found");
33	    let messageContent = htmlBody
34	      ? messageEventContentFromHtml(message, htmlBody)
35	      : messageEventContentFromMarkdown(message);
36	    if (mentions) messageContent = messageContent.withMentions(mentions);
37	    await timeline.send(messageContent);
38	  };
39	
40	  public static replyToMessage = async (
41	    roomId: string,
42	    message: string,
43	    eventId: string,
44	    mentions?: Mentions,
45	    htmlBody?: string,
46	  ) => {
47	    const room = MatrixCore.getRoom(roomId);
48	    const timeline = await room.timeline();
49	    if (!timeline) throw new Error("Timeline not found");
50	    let messageContent = htmlBody
51	      ? messageEventContentFromHtml(message, htmlBody)
52	      : messageEventContentFromMarkdown(message);
53	    if (mentions) messageContent = messageContent.withMentions(mentions);
54	    await timeline.sendReply(messageContent, eventId);
55	  };
56	
57	  public static editMessage = async (
58	    roomId: string,
59	    event: EventTimelineItem,
60	    message: string,
61	    mentions?: Mentions,
62	    htmlBody?: string,
63	  ) => {
64	    const room = MatrixCore.getRoom(roomId);
65	    const timeline = await room.timeline();
66	    if (!timeline) throw new Error("Timeline not found");
67	
68	    if (!event.eventOrTransactionId) {
69	      throw new Error("Event is missing event or transaction id");
70	    }
71	
72	    let messageContent = htmlBody
73	      ? messageEventContentFromHtml(message, htmlBody)
74	      : messageEventContentFromMarkdown(message);
75	    if (mentions) messageContent = messageContent.withMentions(mentions);
76	
77	    const editedContent = EditedContent.RoomMessage.new({
78	      content: messageContent,
79	    });
80	    await timeline.edit(event.eventOrTransactionId, editedContent);
81	  };
82	
83	  public static reportMessage = async (
84	    roomId: string,
85	    event: EventTimelineItem,
86	    reason: string,
87	  ) => {
88	    const room = MatrixCore.getRoom(roomId);
89	    const eventId = getEventId(event);
90	    if (!eventId) throw new Error("Event is missing event id");
91	    await room.reportContent(eventId, undefined, reason);
92	  };
93	
94	  public static deleteMessage = async (
95	    roomId: string,
96	    event: EventTimelineItem,
97	  ) => {
98	    const room = MatrixCore.getRoom(roomId);
99	    const eventId = getEventId(event);
100	    if (!eventId) throw new Error("Event is missing event id");
101	    await room.redact(eventId, undefined);
102	  };
103	
104	  public static forwardMessage = async (
105	    roomId: string,
106	    event: EventTimelineItem,
107	    messageType: ForwardMessageType,
108	  ) => {
109	    const client = MatrixCore.getClient();
110	    const room = MatrixCore.getRoom(roomId);
111	    const timeline = await room.timeline();
112	    if (!timeline) throw new Error("Timeline not found");
113	
114	    if (messageType === "text") {
115	      const textContent = this.getTextContent(event);
116	      if (!textContent) throw new Error("Text content not found");
117	      await timeline.send(messageEventContentFromMarkdown(textContent));
118	      return;
119	    }
120	
121	    if (messageType === "image") {
122	      const imageContent = this.getImageContent(event);
123	      if (!imageContent) throw new Error("Image content not found");
124	
125	      const mediaFile = await client.getMediaFile(
126	        imageContent.source,
127	        imageContent.filename,
128	        imageContent.info?.mimetype || "image/jpeg",
129	        true,
130	        undefined,
131	      );
132	      const filePath = mediaFile.path();
133	      const fileSource: UploadParameters = {
134	        source: new UploadSource.File({ filename: filePath }),
135	        caption: imageContent.caption || undefined,
136	        formattedCaption: undefined,
137	        mentions: undefined,
138	        inReplyTo: undefined,
139	      };
140	      const imageHandle = timeline.sendImage(
141	        fileSource,
142	        new UploadSource.File({ filename: filePath }),
143	        {
144	          height: imageContent.info?.height || BigInt(0),
145	          width: imageContent.info?.width || BigInt(0),
146	          mimetype: imageContent.info?.mimetype || "image/jpeg",
147	          size: imageContent.info?.size || BigInt(0),
148	          thumbnailInfo: imageContent.info?.thumbnailInfo,
149	          thumbnailSource: undefined,
150	          blurhash: imageContent.info?.blurhash || "",
151	          isAnimated: false,
152	        },
153	      );
154	      await imageHandle.join();
155	      return;
156	    }
157	
158	    if (messageType === "video") {
159	      const videoContent = this.getVideoContent(event);
160	      if (!videoContent) throw new Error("Video content not found");
161	
162	      const mediaFile = await client.getMediaFile(
163	        videoContent.source,
164	        videoContent.filename,
165	        videoContent.info?.mimetype || "video/mp4",
166	        true,
167	        undefined,
168	      );
169	      const filePath = mediaFile.path();
170	      const fileSource: UploadParameters = {
171	        source: new UploadSource.File({ filename: filePath }),
172	        caption: videoContent.caption || undefined,
173	        formattedCaption: undefined,
174	        mentions: undefined,
175	        inReplyTo: undefined,
176	      };
177	      const videoHandle = timeline.sendVideo(
178	        fileSource,
179	        new UploadSource.File({ filename: filePath }),
180	        {
181	          height: videoContent.info?.height || BigInt(0),
182	          width: videoContent.info?.width || BigInt(0),
183	          mimetype: videoContent.info?.mimetype || "video/mp4",
184	          size: videoContent.info?.size || BigInt(0),
185	          duration: videoContent.info?.duration || 0,
186	          thumbnailInfo: videoContent.info?.thumbnailInfo,
187	          thumbnailSource: undefined,
188	          blurhash: videoContent.info?.blurhash || "",
189	        },
190	      );
191	      await videoHandle.join();
192	      return;
193	    }
194	
195	    if (messageType === "audio") {
196	      const audioContent = this.getAudioContent(event);
197	      if (!audioContent) throw new Error("Audio content not found");
198	
199	      const mediaFile = await client.getMediaFile(
200	        audioContent.source,
201	        audioContent.filename,
202	        audioContent.info?.mimetype || "audio/mpeg",
203	        true,
204	        undefined,
205	      );
206	      const filePath = mediaFile.path();
207	      const fileSource: UploadParameters = {
208	        source: new UploadSource.File({ filename: filePath }),
209	        caption: undefined,
210	        formattedCaption: undefined,
211	        mentions: undefined,
212	        inReplyTo: undefined,
213	      };
214	      const audioHandle = timeline.sendAudio(fileSource, {
215	        mimetype: audioContent.info?.mimetype || "audio/mpeg",
216	        size: audioContent.info?.size || BigInt(0),
217	        duration: audioContent.info?.duration || 0,
218	      });
219	      await audioHandle.join();
220	      return;
221	    }
222	
223	    if (messageType === "file") {
224	      const fileContent = this.getFileContent(event);
225	      if (!fileContent) throw new Error("File content not found");
226	
227	      const mediaFile = await client.getMediaFile(
228	        fileContent.source,
229	        fileContent.filename,
230	        fileContent.info?.mimetype || "application/octet-stream",
231	        true,
232	        undefined,
233	      );
234	      const filePath = mediaFile.path();
235	      const fileHandle = timeline.sendFile(
236	        {
237	          source: new UploadSource.File({ filename: filePath }),
238	          caption: undefined,
239	          formattedCaption: undefined,
240	          mentions: undefined,
241	          inReplyTo: undefined,
242	        },
243	        {
244	          size: fileContent.info?.size || BigInt(0),
245	          mimetype: fileContent.info?.mimetype || "application/octet-stream",
246	          thumbnailInfo: undefined,
247	          thumbnailSource: undefined,
248	        },
249	      );
250	      await fileHandle.join();
251	      return;
252	    }
253	
254	    throw new Error(`Unsupported message type: ${messageType}`);
255	  };
256	
257	  public static sendAttachment = async (
258	    roomId: string,
259	    attachment: DocumentPickerResponse,
260	  ) => {
261	    const room = MatrixCore.getRoom(roomId);
262	    const timeline = await room.timeline();
263	    if (!timeline) throw new Error("Timeline not found");
264	    const fileHandle = timeline.sendFile(
265	      {
266	        source: new UploadSource.File({
267	          filename: decodeURIComponent(attachment.uri.replace("file://", "")),
268	        }),
269	        caption: undefined,
270	        formattedCaption: undefined,
271	        mentions: undefined,
272	        inReplyTo: undefined,
273	      },
274	      {
275	        size: BigInt(attachment.size || 0),
276	        mimetype: attachment.type || "application/octet-stream",
277	        thumbnailInfo: undefined,
278	        thumbnailSource: undefined,
279	      },
280	    );
281	    await fileHandle.join();
282	  };
283	
284	  public static sendMedia = async (
285	    roomId: string,
286	    asset: Asset,
287	    caption?: string,
288	  ) => {
289	    if (!asset?.uri) throw new Error("No uri found");
290	    const room = MatrixCore.getRoom(roomId);
291	    const timeline = await room.timeline();
292	    if (!timeline) throw new Error("Timeline not found");
293	
294	    const type = asset.type ?? "image/jpeg";
295	    const assetWidth = asset.width ?? 0;
296	    const assetHeight = asset.height ?? 0;
297	    const isVideo = type.startsWith("video/");
298	
299	    const fileSource: UploadParameters = {
300	      source: new UploadSource.File({
301	        filename: decodeURIComponent(asset.uri.replace("file://", "")),
302	      }),
303	      caption: caption || undefined,
304	      formattedCaption: undefined,
305	      mentions: undefined,
306	      inReplyTo: undefined,
307	    };
308	
309	    if (isVideo) {
310	      const videoHandle = timeline.sendVideo(
311	        fileSource,
312	        new UploadSource.File({
313	          filename: decodeURIComponent(asset.uri.replace("file://", "")),
314	        }),
315	        {
316	          height: BigInt(assetHeight),
317	          width: BigInt(assetWidth),
318	          mimetype: type,
319	          size: BigInt(asset.fileSize ?? 0),
320	          duration: asset.duration ? Math.round(asset.duration * 1000) : 0,
321	          thumbnailInfo: {
322	            height: BigInt(assetHeight),
323	            width: BigInt(assetWidth),
324	            mimetype: type,
325	            size: BigInt(asset.fileSize ?? 0),
326	          },
327	          thumbnailSource: undefined,
328	          blurhash: "",
329	        },
330	      );
331	      await videoHandle.join();
332	    } else {
333	      const imageHandle = timeline.sendImage(
334	        fileSource,
335	        new UploadSource.File({
336	          filename: decodeURIComponent(asset.uri.replace("file://", "")),
337	        }),
338	        {
339	          height: BigInt(assetHeight),
340	          width: BigInt(assetWidth),
341	          mimetype: type,
342	          size: BigInt(asset.fileSize ?? 0),
343	          thumbnailInfo: {
344	            height: BigInt(assetHeight),
345	            width: BigInt(assetWidth),
346	            mimetype: type,
347	            size: BigInt(asset.fileSize ?? 0),
348	          },
349	          thumbnailSource: undefined,
350	          blurhash: "",
351	          isAnimated: false,
352	        },
353	      );
354	      await imageHandle.join();
355	    }
356	  };
357	
358	  public static sendEvent = async (
359	    roomId: string,
360	    eventType: string,
361	    content: string,
362	  ) => {
363	    const room = MatrixCore.getRoom(roomId);
364	    await room.sendRaw(eventType, content);
365	  };
366	
367	  public static getSeenBy = (event: EventTimelineItem) => event.readReceipts;
368	
369	  public static getReadReceiptUserIds = (
370	    event: EventTimelineItem,
371	  ): string[] => {
372	    const userIds = Array.from(event.readReceipts.keys());
373	    return userIds.filter((userId) => userId !== event.sender);
374	  };
375	
376	  public static isUser = (event: EventTimelineItem) => event.isOwn;
377	
378	  public static getSenderDetails = (event: EventTimelineItem) => {
379	    if (!MatrixCore.instance) return null;
380	    const senderId = event.sender;
381	    return senderId ? MatrixCore.instance.getProfile(senderId) : null;
382	  };
383	
384	  // Pinned messages
385	
386	  public static getPinnedEventIds = async (
387	    roomId: string,
388	  ): Promise<string[]> => {
389	    const room = MatrixCore.getRoom(roomId);
390	    const roomInfo = await room.roomInfo();
391	    return roomInfo.pinnedEventIds || [];
392	  };
393	
394	  public static pinMessage = async (roomId: string, eventId: string) => {
395	    const room = MatrixCore.getRoom(roomId);
396	    const timeline = await room.timeline();
397	    if (!timeline) throw new Error("Timeline not found");
398	    await timeline.pinEvent(eventId);
399	  };
400	
401	  public static unpinMessage = async (roomId: string, eventId: string) => {
402	    const room = MatrixCore.getRoom(roomId);
403	    const timeline = await room.timeline();
404	    if (!timeline) throw new Error("Timeline not found");
405	    await timeline.unpinEvent(eventId);
406	  };
407	
408	  public static isMessagePinned = async (
409	    roomId: string,
410	    eventId: string,
411	  ): Promise<boolean> => {
412	    const pinnedEvents = await this.getPinnedEventIds(roomId);
413	    return pinnedEvents.includes(eventId);
414	  };
415	
416	  // Private content extractors
417	
418	  private static getTextContent = (event: EventTimelineItem): string | null => {
419	    if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
420	      const kind = event.content.inner.content.kind;
421	      if (kind?.tag === MsgLikeKind_Tags.Message) {
422	        return kind.inner.content.body;
423	      }
424	    }
425	    return null;
426	  };
427	
428	  private static getImageContent = (
429	    event: EventTimelineItem,
430	  ): ImageMessageContent | null => {
431	    if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
432	      const kind = event.content.inner.content.kind;
433	      if (kind?.tag === MsgLikeKind_Tags.Message) {
434	        const msgType = kind.inner.content.msgType;
435	        if (msgType?.tag === MessageType_Tags.Image) {
436	          return msgType.inner.content;
437	        }
438	      }
439	    }
440	    return null;
441	  };
442	
443	  private static getVideoContent = (
444	    event: EventTimelineItem,
445	  ): VideoMessageContent | null => {
446	    if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
447	      const kind = event.content.inner.content.kind;
448	      if (kind?.tag === MsgLikeKind_Tags.Message) {
449	        const msgType = kind.inner.content.msgType;
450	        if (msgType?.tag === MessageType_Tags.Video) {
451	          return msgType.inner.content;
452	        }
453	      }
454	    }
455	    return null;
456	  };
457	
458	  private static getAudioContent = (
459	    event: EventTimelineItem,
460	  ): AudioMessageContent | null => {
461	    if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
462	      const kind = event.content.inner.content.kind;
463	      if (kind?.tag === MsgLikeKind_Tags.Message) {
464	        const msgType = kind.inner.content.msgType;
465	        if (msgType?.tag === MessageType_Tags.Audio) {
466	          return msgType.inner.content;
467	        }
468	      }
469	    }
470	    return null;
471	  };
472	
473	  private static getFileContent = (
474	    event: EventTimelineItem,
475	  ): FileMessageContent | null => {
476	    if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
477	      const kind = event.content.inner.content.kind;
478	      if (kind?.tag === MsgLikeKind_Tags.Message) {
479	        const msgType = kind.inner.content.msgType;
480	        if (msgType?.tag === MessageType_Tags.File) {
481	          return msgType.inner.content;
482	        }
483	      }
484	    }
485	    return null;
486	  };
487	}
